def _official_codex_disclosure_has_closed_grammar(value: object) -> bool:
    if not isinstance(value, str):
        return False
    return [line.strip() for line in value.split("\n") if line.strip()] == (
        _GITHUB_CODEX_DISCLOSURE.split("\n")
    )


def _strip_official_codex_disclosure(value: str) -> tuple[str, bool]:
    expected_lines = _GITHUB_CODEX_DISCLOSURE.split("\n")
    nonblank_tail: collections.deque[tuple[int, str]] = collections.deque(
        maxlen=len(expected_lines)
    )
    line_start = 0
    for physical_line in value.split("\n"):
        stripped_line = physical_line.strip()
        if stripped_line:
            nonblank_tail.append((line_start, stripped_line))
        line_start += len(physical_line) + 1
    if [line for _, line in nonblank_tail] != expected_lines:
        return (value, False)
    suffix_start = nonblank_tail[0][0]
    boundary = suffix_start - 2
    if (
        boundary < 0
        or value[boundary:suffix_start] != "\n\n"
        or (boundary > 0 and value[boundary - 1] == "\n")
    ):
        return (value, False)
    suffix = value[suffix_start:]
    if not _official_codex_disclosure_has_closed_grammar(suffix):
        return (value, False)
    return (value[:boundary], True)


def _github_codex_clean_issue_marker(
    normalized_body: str,
) -> tuple[str, str] | None:
    core, _ = _strip_official_codex_disclosure(normalized_body)
    clean_lead = "Codex Review: Didn't find any major issues."
    for tagline in _GITHUB_CODEX_CLEAN_TAGLINES:
        marker_prefix = f"{clean_lead}{tagline}\n\n**Reviewed commit:** `"
        if not core.startswith(marker_prefix) or not core.endswith("`"):
            continue
        commit_ref = core[len(marker_prefix) : -1]
        if re.fullmatch(r"[0-9a-f]{10}|[0-9a-f]{40}", commit_ref) is not None:
            return (f"**Reviewed commit:** `{commit_ref}`", commit_ref)
    return None


def _normalize_github_codex_body(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    normalized = (
        value.replace("\r\n", "\n")
        .replace("\r", "\n")
        .replace("\v", "\n")
        .replace("\f", "\n")
        .replace("\u0085", "\n")
        .replace("\u2028", "\n")
        .replace("\u2029", "\n")
    )
    if any(
        0xD800 <= codepoint <= 0xDFFF
        or codepoint == 0
        or (
            (codepoint < 0x20 or 0x7F <= codepoint <= 0x9F)
            and codepoint not in (0x09, 0x0A)
        )
        for codepoint in map(ord, normalized)
    ):
        return None
    return normalized.strip("\t\n ")


def _github_codex_issue_terminal_looking(normalized_body: object) -> bool:
    if not isinstance(normalized_body, str):
        return False
    first_line = normalized_body.split("\n", 1)[0]
    marker_index = first_line.find("Codex Review")
    return 0 <= marker_index < 64 and all(
        not char.isascii() or not char.isalnum() for char in first_line[:marker_index]
    )


def _github_codex_issue_body_semantic(
    raw_body: object,
    *,
    repository: str,
    head: str,
    allow_foreign_finding_sha: bool = False,
    resolved_clean_commit: str | None = None,
) -> tuple[str, str | None]:
    body = _normalize_github_codex_body(raw_body)
    if body is None or not _github_codex_issue_terminal_looking(body):
        return ("nonterminal", None)
    first_line, *later_lines = body.split("\n")
    marker_index = first_line.find("Codex Review")
    provider_first_line = first_line[marker_index:]
    progress_stems = {
        "Codex Review in progress",
        "Codex Review still in progress",
    }
    progress_only = provider_first_line in progress_stems or provider_first_line in {
        f"{stem}." for stem in progress_stems
    }
    if not progress_only:
        for stem in progress_stems:
            prefix = f"{stem}: "
            detail = (
                provider_first_line[len(prefix) :]
                if provider_first_line.startswith(prefix)
                else ""
            )
            if (
                detail
                and len(detail) <= 160
                and all(
                    not (ord(char) < 0x20 or 0x7F <= ord(char) <= 0x9F)
                    for char in detail
                )
            ):
                progress_only = True
                break
    if progress_only and not any(line for line in later_lines):
        return ("nonterminal", None)

    clean_marker = _github_codex_clean_issue_marker(body)
    if clean_marker is not None:
        _, commit_ref = clean_marker
        resolved_commit = commit_ref if len(commit_ref) == 40 else resolved_clean_commit
        if (
            isinstance(resolved_commit, str)
            and re.fullmatch(r"[0-9a-f]{40}", resolved_commit) is not None
            and resolved_commit.startswith(commit_ref)
            and resolved_commit == head
        ):
            return ("clean", resolved_commit)

    finding_body = body
    disclosure_suffix = f"\n\n{_GITHUB_CODEX_DISCLOSURE}"
    if finding_body.endswith(disclosure_suffix):
        finding_body = finding_body[: -len(disclosure_suffix)]
    lines = finding_body.split("\n")
    if len(lines) >= 2 and lines[0] == "### 💡 Codex Review":
        finding_pattern = re.compile(
            r"^- \[P[0-3]\] (?P<title>.{1,240}) — "
            + rf"https://github\.com/{re.escape(repository)}/blob/"
            + r"(?P<sha>[0-9a-f]{40})/"
            + r"(?P<path>(?:[A-Za-z0-9._~!$&'()*+,;=:@/-]|%[0-9A-F]{2})+)"
            + r"#L[1-9][0-9]*(?:-L[1-9][0-9]*)?$"
        )
        shas: set[str] = set()
        for line in lines[1:]:
            match = finding_pattern.fullmatch(line)
            if match is None:
                return ("malformed", None)
            title = match.group("title")
            try:
                decoded_path = urllib.parse.unquote_to_bytes(
                    match.group("path")
                ).decode("utf-8", errors="strict")
            except UnicodeDecodeError:
                return ("malformed", None)
            if (
                title != title.strip("\t ")
                or " — " in title
                or any(unicodedata.category(char) == "Cc" for char in title)
                or any(
                    segment in {"", ".", ".."} for segment in decoded_path.split("/")
                )
            ):
                return ("malformed", None)
            shas.add(match.group("sha"))
        if len(shas) == 1:
            finding_sha = next(iter(shas))
            if finding_sha == head or allow_foreign_finding_sha:
                return ("findings", finding_sha)
    return ("malformed", None)


def _github_codex_inline_parent_container(commit_id: str) -> str:
    return "\n".join(
        (
            "### 💡 Codex Review",
            "Here are some automated review suggestions for this pull request.",
            f"**Reviewed commit:** `{commit_id}`",
            "",
            _GITHUB_CODEX_DISCLOSURE,
        )
    )


def _github_codex_legacy_top_level_review_finding_commit(
    normalized_body: object,
    *,
    repository: str,
    native_commit_id: str,
) -> str | None:
    if (
        not isinstance(normalized_body, str)
        or re.fullmatch(r"[0-9a-f]{40}", native_commit_id) is None
        or "\t" in normalized_body
    ):
        return None
    core, has_disclosure = _strip_official_codex_disclosure(normalized_body)
    if not has_disclosure:
        return None
    if core.endswith("\n    "):
        grammatical_core = core[:-5]
    elif core == core.rstrip(" \n"):
        grammatical_core = core
    else:
        return None
    lines = grammatical_core.split("\n")
    if len(lines) < 6 or lines[:2] != ["### 💡 Codex Review", ""]:
        return None
    blob_url = re.fullmatch(
        rf"https://github\.com/{re.escape(repository)}/blob/"
        r"(?P<sha>[0-9a-f]{40})/"
        r"(?P<path>(?:[A-Za-z0-9._~!$&'()*+,;=:@/-]|%[0-9A-F]{2})+)"
        r"#L(?P<start>[1-9][0-9]*)(?:-L(?P<end>[1-9][0-9]*))?",
        lines[2],
    )
    badge = re.fullmatch(
        r"\*\*<sub><sub>!\[P(?P<priority>[0-3]) Badge\]"
        r"\(https://img\.shields\.io/badge/P(?P=priority)-"
        r"(?P<color>red|orange|yellow|lightgrey)\?style=flat\)"
        r"</sub></sub>  (?P<title>.{1,240})\*\*",
        lines[3],
    )
    if (
        blob_url is None
        or badge is None
        or lines[4] != ""
        or blob_url.group("sha") != native_commit_id
        or badge.group("color")
        != {"0": "red", "1": "orange", "2": "yellow", "3": "lightgrey"}[
            badge.group("priority")
        ]
    ):
        return None
    try:
        decoded_path = urllib.parse.unquote_to_bytes(blob_url.group("path")).decode(
            "utf-8", errors="strict"
        )
    except UnicodeDecodeError:
        return None
    end_line = blob_url.group("end")
    if (
        any(segment in {"", ".", ".."} for segment in decoded_path.split("/"))
        or "\\" in decoded_path
        or any(unicodedata.category(char) == "Cc" for char in decoded_path)
        or (end_line is not None and int(end_line) < int(blob_url.group("start")))
    ):
        return None
    title = badge.group("title")
    prose_lines = lines[5:]
    prose = "\n".join(prose_lines)
    bounded_text = f"{title}\n{prose}"
    if (
        title != title.strip(" ")
        or "**" in title
        or not prose.strip(" \n")
        or prose != prose.rstrip(" \n")
        or len(prose) > 8_000
        or len(prose_lines) > 32
        or any(len(line) > 2_000 for line in prose_lines)
        or any(
            char != "\n" and unicodedata.category(char) == "Cc" for char in bounded_text
        )
        or "<" in bounded_text
        or ">" in bounded_text
        or re.search(
            r"(?:[A-Za-z][A-Za-z0-9+.-]*):(?=\S)|www\.",
            bounded_text,
            flags=re.IGNORECASE,
        )
        is not None
        or re.search(
            r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40}(?![0-9A-Fa-f])",
            bounded_text,
        )
        is not None
        or len(re.findall(r"https?://", core, flags=re.IGNORECASE)) != 2
        or len(
            re.findall(
                r"(?<![0-9A-Fa-f])[0-9a-f]{40}(?![0-9A-Fa-f])",
                core,
            )
        )
        != 1
    ):
        return None
    return native_commit_id


def _github_codex_invalid_review_state_terminal_signal(
    raw_body: object,
    *,
    state: object,
    has_associated_children: bool,
) -> bool:
    if state == "PENDING" or state in {
        "APPROVED",
        "COMMENTED",
        "CHANGES_REQUESTED",
    }:
        return False
    if state == "DISMISSED":
        return True
    body = _normalize_github_codex_body(raw_body)
    return body != "" or has_associated_children


def _github_codex_review_body_semantic(
    raw_body: object,
    *,
    repository: str,
    state: object,
    commit_id: str,
    current_head: str,
    has_associated_children: bool,
    has_target_children: bool,
    allow_legacy_native_review: bool = False,
) -> tuple[str, str | None]:
    if type(allow_legacy_native_review) is not bool:
        return ("malformed", None)
    body = _normalize_github_codex_body(raw_body)
    if body is None:
        return ("malformed", None)
    if _github_codex_invalid_review_state_terminal_signal(
        body,
        state=state,
        has_associated_children=has_associated_children,
    ):
        return ("malformed", None)
    if state == "PENDING" or state not in {
        "APPROVED",
        "COMMENTED",
        "CHANGES_REQUESTED",
    }:
        return ("nonterminal", None)
    if state == "APPROVED":
        if body == "No findings." and has_target_children:
            return ("findings", commit_id)
        if commit_id == current_head and body == "No findings.":
            return ("clean", commit_id)
        return ("malformed", None)
    if allow_legacy_native_review:
        legacy_finding_commit = _github_codex_legacy_top_level_review_finding_commit(
            body,
            repository=repository,
            native_commit_id=commit_id,
        )
        if legacy_finding_commit is not None:
            if (
                state in {"COMMENTED", "CHANGES_REQUESTED"}
                and not has_associated_children
                and not has_target_children
            ):
                return ("findings", legacy_finding_commit)
            return ("malformed", None)
    top_level_semantic, finding_commit = _github_codex_issue_body_semantic(
        body,
        repository=repository,
        head=commit_id,
        allow_foreign_finding_sha=True,
    )
    if (
        top_level_semantic == "findings"
        and finding_commit == commit_id
        and state in {"COMMENTED", "CHANGES_REQUESTED"}
    ):
        return ("findings", finding_commit)
    if (
        state == "COMMENTED"
        and has_target_children
        and body in {"", _github_codex_inline_parent_container(commit_id)}
    ):
        return ("findings", commit_id)
    return ("malformed", None)


def _format_github_rfc3339_seconds(value: object) -> object:
    if type(value) is not int or value <= 0:
        return value
    try:
        instant = datetime.datetime.fromtimestamp(value, datetime.timezone.utc)
    except (OSError, OverflowError, ValueError):
        return value
    return instant.strftime("%Y-%m-%dT%H:%M:%SZ")


def _parse_github_rfc3339_seconds(value: object) -> int | None:
    if (
        not isinstance(value, str)
        or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}T"
            r"[0-9]{2}:[0-9]{2}:[0-9]{2}Z",
            value,
        )
        is None
    ):
        return None
    try:
        instant = datetime.datetime.strptime(
            value,
            "%Y-%m-%dT%H:%M:%SZ",
        ).replace(tzinfo=datetime.timezone.utc)
    except ValueError:
        return None
    if instant.strftime("%Y-%m-%dT%H:%M:%SZ") != value:
        return None
    timestamp = instant.timestamp()
    return int(timestamp) if timestamp.is_integer() and timestamp > 0 else None


def _review_thread_pages(
    children: list[dict[str, object]],
    *,
    parent_review_id: int,
    resolved: bool = False,
    resolutions: list[bool] | None = None,
) -> dict[str, object]:
    if resolutions is None:
        resolutions = [resolved for _ in children]
    if len(resolutions) != len(children) or any(
        type(item) is not bool for item in resolutions
    ):
        raise AssertionError("thread resolutions must match children")
    nodes: list[dict[str, object]] = []
    for child, child_resolved in zip(children, resolutions, strict=True):
        child_id = child["id"]
        child_url = child["url"]
        assert type(child_id) is int
        assert isinstance(child_url, str)
        nodes.append(
            {
                "id": f"PRRT_{child_id}",
                "isResolved": child_resolved,
                "isOutdated": False,
                "comments": {
                    "pagination_complete": True,
                    "pages": [
                        {
                            "after": None,
                            "nodes": [
                                {
                                    "id": f"PRRC_{child_id}",
                                    "fullDatabaseId": str(child_id),
                                    "url": child_url,
                                    "pullRequestReview": {
                                        "id": f"PRR_{parent_review_id}",
                                        "fullDatabaseId": str(parent_review_id),
                                    },
                                }
                            ],
                            "pageInfo": {
                                "hasNextPage": False,
                                "endCursor": None,
                            },
                        }
                    ],
                },
            }
        )
    return {
        "endpoint": "https://api.github.com/graphql",
        "pagination_complete": True,
        "pages": [
            {
                "after": None,
                "nodes": nodes,
                "pageInfo": {
                    "hasNextPage": False,
                    "endCursor": None,
                },
            }
        ],
    }


def _graphql_thread_comment_fixture(
    comment_id: int,
    *,
    parent_id: int | None,
    repository: str = "OWNER/REPO",
    pull_request: int = 1,
) -> dict[str, object]:
    return {
        "id": f"PRRC_{comment_id}",
        "fullDatabaseId": str(comment_id),
        "url": (
            f"https://github.com/{repository}/pull/{pull_request}"
            f"#discussion_r{comment_id}"
        ),
        "pullRequestReview": (
            {
                "id": f"PRR_{parent_id}",
                "fullDatabaseId": str(parent_id),
            }
            if parent_id is not None
            else None
        ),
    }


def _selected_review_target_children(
    children: object,
    *,
    repository: str,
    pull_request: int,
    parent_review_id: int,
) -> list[dict[str, object]] | None:
    if not isinstance(children, list):
        return None
    exact_login = "chatgpt-codex-connector[bot]"
    child_fields = {
        "id",
        "url",
        "user_login",
        "user_type",
        "pull_request_review_id",
        "commit_id",
        "original_commit_id",
        "body",
        "normalized_body",
    }
    seen_child_ids: set[int] = set()
    targets: list[dict[str, object]] = []
    for child in children:
        if not isinstance(child, dict):
            return None
        child_id = child.get("id")
        parent_id = child.get("pull_request_review_id")
        login = child.get("user_login")
        user_type = child.get("user_type")
        body = child.get("body")
        normalized_body = _normalize_github_codex_body(body)
        if (
            set(child) != child_fields
            or type(child_id) is not int
            or child_id <= 0
            or child_id in seen_child_ids
            or child.get("url")
            != (
                f"https://github.com/{repository}/pull/{pull_request}"
                f"#discussion_r{child_id}"
            )
            or (
                parent_id is not None and (type(parent_id) is not int or parent_id <= 0)
            )
            or not isinstance(child.get("commit_id"), str)
            or re.fullmatch(r"[0-9a-f]{40}", child["commit_id"]) is None
            or not isinstance(child.get("original_commit_id"), str)
            or re.fullmatch(r"[0-9a-f]{40}", child["original_commit_id"]) is None
            or not isinstance(body, str)
            or normalized_body is None
            or child.get("normalized_body") != normalized_body
        ):
            return None
        seen_child_ids.add(child_id)

        if login == exact_login and user_type == "Bot":
            actor = "exact"
        elif (
            isinstance(login, str)
            and login
            and login != exact_login
            and user_type in {"User", "Bot"}
            and not (user_type == "Bot" and "codex" in login.lower())
        ):
            actor = "different"
        else:
            return None

        if actor == "exact":
            if parent_id is not None and parent_id != parent_review_id:
                return None
            if parent_id == parent_review_id:
                targets.append(child)
    return targets


def _review_thread_findings_from_raw(
    children: object,
    thread_pages: object,
    *,
    repository: str,
    pull_request: int,
    parent_review_id: int,
) -> list[dict[str, object]] | None:
    if not isinstance(children, list) or not isinstance(thread_pages, dict):
        return None
    if (
        set(thread_pages) != {"endpoint", "pagination_complete", "pages"}
        or thread_pages.get("endpoint") != "https://api.github.com/graphql"
        or thread_pages.get("pagination_complete") is not True
        or not isinstance(thread_pages.get("pages"), list)
        or not thread_pages["pages"]
    ):
        return None

    target_children = _selected_review_target_children(
        children,
        repository=repository,
        pull_request=pull_request,
        parent_review_id=parent_review_id,
    )
    if target_children is None:
        return None
    rest_children = {str(child["id"]): child for child in target_children}

    def connection_nodes(
        connection: object,
        *,
        node_keys: set[str],
    ) -> list[dict[str, object]] | None:
        if (
            not isinstance(connection, dict)
            or set(connection) != {"pagination_complete", "pages"}
            or connection.get("pagination_complete") is not True
            or not isinstance(connection.get("pages"), list)
            or not connection["pages"]
        ):
            return None
        pages = connection["pages"]
        expected_after: str | None = None
        nodes: list[dict[str, object]] = []
        for index, page in enumerate(pages):
            if (
                not isinstance(page, dict)
                or set(page) != {"after", "nodes", "pageInfo"}
                or page.get("after") != expected_after
                or not isinstance(page.get("nodes"), list)
            ):
                return None
            page_info = page.get("pageInfo")
            if (
                not isinstance(page_info, dict)
                or set(page_info) != {"hasNextPage", "endCursor"}
                or type(page_info.get("hasNextPage")) is not bool
            ):
                return None
            has_next = page_info["hasNextPage"]
            end_cursor = page_info.get("endCursor")
            if has_next:
                if (
                    index == len(pages) - 1
                    or not isinstance(end_cursor, str)
                    or not end_cursor
                ):
                    return None
                expected_after = end_cursor
            else:
                if index != len(pages) - 1 or (
                    end_cursor is not None
                    and (not isinstance(end_cursor, str) or not end_cursor)
                ):
                    return None
                expected_after = None
            for node in page["nodes"]:
                if not isinstance(node, dict) or set(node) != node_keys:
                    return None
                nodes.append(node)
        return nodes

    thread_connection = {
        "pagination_complete": thread_pages["pagination_complete"],
        "pages": thread_pages["pages"],
    }
    thread_nodes = connection_nodes(
        thread_connection,
        node_keys={"id", "isResolved", "isOutdated", "comments"},
    )
    if thread_nodes is None:
        return None

    mapped_children: dict[str, dict[str, object]] = {}
    thread_ids: set[str] = set()
    graphql_comment_ids: set[str] = set()
    graphql_child_ids: set[str] = set()
    graphql_review_ids: set[str] = set()
    for thread in thread_nodes:
        thread_id = thread.get("id")
        if (
            not isinstance(thread_id, str)
            or not thread_id
            or thread_id in thread_ids
            or type(thread.get("isResolved")) is not bool
            or type(thread.get("isOutdated")) is not bool
        ):
            return None
        thread_ids.add(thread_id)
        comment_nodes = connection_nodes(
            thread.get("comments"),
            node_keys={"id", "fullDatabaseId", "url", "pullRequestReview"},
        )
        if not comment_nodes:
            return None
        for comment in comment_nodes:
            graphql_comment_id = comment.get("id")
            graphql_child_id = comment.get("fullDatabaseId")
            child_id = (
                _canonical_positive_decimal(graphql_child_id)
                if isinstance(graphql_child_id, str)
                else None
            )
            parent = comment.get("pullRequestReview")
            if (
                not isinstance(graphql_comment_id, str)
                or not graphql_comment_id
                or graphql_comment_id in graphql_comment_ids
                or child_id is None
                or child_id in graphql_child_ids
                or comment.get("url")
                != (
                    f"https://github.com/{repository}/pull/{pull_request}"
                    f"#discussion_r{child_id}"
                )
                or (
                    parent is not None
                    and (
                        not isinstance(parent, dict)
                        or set(parent) != {"id", "fullDatabaseId"}
                        or not isinstance(parent.get("id"), str)
                        or not parent["id"]
                        or not isinstance(parent.get("fullDatabaseId"), str)
                        or _canonical_positive_decimal(parent.get("fullDatabaseId"))
                        is None
                    )
                )
            ):
                return None
            graphql_comment_ids.add(graphql_comment_id)
            graphql_child_ids.add(child_id)
            if child_id not in rest_children:
                continue
            if (
                child_id in mapped_children
                or comment.get("url") != rest_children[child_id].get("url")
                or not isinstance(parent, dict)
                or (
                    _canonical_positive_decimal(parent.get("fullDatabaseId"))
                    != str(parent_review_id)
                )
            ):
                return None
            graphql_review_ids.add(parent["id"])
            mapped_children[child_id] = {
                "child_id": int(child_id),
                "graphql_comment_id": graphql_comment_id,
                "thread_id": thread_id,
                "is_resolved": thread["isResolved"],
                "is_outdated": thread["isOutdated"],
                "pull_request_review_id": parent_review_id,
            }
    if set(mapped_children) != set(rest_children):
        return None
    if mapped_children and len(graphql_review_ids) != 1:
        return None
    return [mapped_children[child_id] for child_id in rest_children]


def _has_python_shebang(path: pathlib.Path) -> bool:
    with path.open("rb") as handle:
        first_line = handle.readline(256)
    return first_line.startswith(b"#!") and b"python" in first_line.lower()


def _ci_contract_context(skill_root: pathlib.Path) -> tuple[pathlib.Path, str]:
    layouts = sorted(
        CI_PROFILE_BY_SKILL_LAYOUT.items(),
        key=lambda item: len(item[0].parts),
        reverse=True,
    )
    for layout, profile in layouts:
        layout_depth = len(layout.parts)
        if skill_root.parts[-layout_depth:] != layout.parts:
            continue
        repo_root = skill_root.parents[layout_depth - 1]
        if repo_root / layout != skill_root:
            continue
        return repo_root, profile
    raise AssertionError(f"unsupported review skill layout: {skill_root}")


REPO_ROOT, CI_PROFILE = _ci_contract_context(SKILL_ROOT)


def _repository_policy_scope_root(
    repo_root: pathlib.Path,
    profile: str,
) -> pathlib.Path:
    try:
        relative_scope = REPOSITORY_POLICY_SCOPE_BY_PROFILE[profile]
    except KeyError as error:
        raise AssertionError(
            f"unsupported repository policy profile: {profile}"
        ) from error
    return repo_root / relative_scope


def _repository_agents_path(repo_root: pathlib.Path, profile: str) -> pathlib.Path:
    return _repository_policy_scope_root(repo_root, profile) / "AGENTS.md"


def _github_provider_repository_policy_files(
    repo_root: pathlib.Path,
    profile: str,
) -> dict[str, str]:
    policy_paths: dict[str, pathlib.Path] = {}
    if profile == "canonical":
        policy_paths = {
            "repository policy": _repository_agents_path(repo_root, profile),
            "change delivery": (
                _repository_policy_scope_root(repo_root, profile)
                / "skills/change-delivery-workflow/SKILL.md"
            ),
        }
    elif profile != "private":
        raise AssertionError(f"unsupported repository policy profile: {profile}")
    return {
        name: path.read_text(encoding="utf-8") for name, path in policy_paths.items()
    }


