    def test_official_codex_disclosure_parser_checks_one_tail_candidate(self) -> None:
        global _official_codex_disclosure_has_closed_grammar

        original_validator = _official_codex_disclosure_has_closed_grammar
        validation_calls = 0

        def counted_validator(value: object) -> bool:
            nonlocal validation_calls
            validation_calls += 1
            return original_validator(value)

        near_miss_disclosure = _GITHUB_CODEX_DISCLOSURE.replace(
            "Reviews are triggered",
            "Reviews might be triggered",
        )
        many_boundary_near_miss = (
            "Result"
            + "".join(f"\n\nnot-disclosure-{index}" for index in range(4096))
            + f"\n\n{near_miss_disclosure}"
        )
        _official_codex_disclosure_has_closed_grammar = counted_validator
        try:
            self.assertEqual(
                _strip_official_codex_disclosure(many_boundary_near_miss),
                (many_boundary_near_miss, False),
            )
        finally:
            _official_codex_disclosure_has_closed_grammar = original_validator
        self.assertLessEqual(validation_calls, 1)

        for extra_lf_count in (1, 3, 4):
            value = "Result" + ("\n" * extra_lf_count) + _GITHUB_CODEX_DISCLOSURE
            with self.subTest(disclosure_boundary_lf_count=extra_lf_count):
                self.assertEqual(
                    _strip_official_codex_disclosure(value),
                    (value, False),
                )
        exact_value = f"Result\n\n{_GITHUB_CODEX_DISCLOSURE}"
        self.assertEqual(
            _strip_official_codex_disclosure(exact_value),
            ("Result", True),
        )

    def test_github_codex_terminal_grammar_fixture_matrix(self) -> None:
        authority = (
            SKILL_ROOT / "references/github-codex-evidence-authority.md"
        ).read_text(encoding="utf-8")
        current_sha = "0123456789abcdef0123456789abcdef01234567"
        other_sha = "fedcba9876543210fedcba9876543210fedcba98"
        review_id = 123456789
        disclosure = _GITHUB_CODEX_DISCLOSURE
        eligible_finding_commits = {current_sha, other_sha}

        def inline_container(commit_id: str) -> str:
            return "\n".join(
                (
                    "### 💡 Codex Review",
                    "Here are some automated review suggestions for this pull request.",
                    f"**Reviewed commit:** `{commit_id}`",
                    "",
                    disclosure,
                )
            )

        def clone(value: dict[str, object]) -> dict[str, object]:
            return json.loads(json.dumps(value))

        def normalize_body(value: object) -> str | None:
            return _normalize_github_codex_body(value)

        finding_line = re.compile(
            r"^- \[P[0-3]\] (?P<title>.{1,240}) — "
            r"https://github\.com/OWNER/REPO/blob/"
            r"(?P<sha>[0-9a-f]{40})/"
            r"(?P<path>(?:[A-Za-z0-9._~!$&'()*+,;=:@/-]|%[0-9A-F]{2})+)"
            r"#L[1-9][0-9]*(?:-L[1-9][0-9]*)?$"
        )

        def finding_sha(body: str) -> str | None:
            finding_body = body
            disclosure_suffix = f"\n\n{disclosure}"
            if finding_body.endswith(disclosure_suffix):
                finding_body = finding_body[: -len(disclosure_suffix)]
            lines = finding_body.split("\n")
            if len(lines) < 2 or lines[0] != "### 💡 Codex Review":
                return None
            shas: set[str] = set()
            for line in lines[1:]:
                match = finding_line.fullmatch(line)
                if match is None:
                    return None
                title = match.group("title")
                path = match.group("path")
                try:
                    decoded_path = urllib.parse.unquote_to_bytes(path).decode(
                        "utf-8", errors="strict"
                    )
                except UnicodeDecodeError:
                    return None
                if (
                    title != title.strip("\t ")
                    or " — " in title
                    or any(unicodedata.category(char) == "Cc" for char in title)
                    or any(
                        segment in ("", ".", "..")
                        for segment in decoded_path.split("/")
                    )
                ):
                    return None
                shas.add(match.group("sha"))
            return next(iter(shas)) if len(shas) == 1 else None

        def exact_provider(record: dict[str, object]) -> bool:
            return (
                record.get("user_login") == "chatgpt-codex-connector[bot]"
                and record.get("user_type") == "Bot"
            )

        def exact_inline_child(
            record: object,
            *,
            parent_id: int,
            commit_id: str,
        ) -> bool:
            if not isinstance(record, dict):
                return False
            child_id = record.get("id")
            body = normalize_body(record.get("body"))
            expected_keys = {
                "id",
                "url",
                "user_login",
                "user_type",
                "pull_request_review_id",
                "commit_id",
                "original_commit_id",
                "body",
                "normalized_body",
            }
            return (
                set(record) == expected_keys
                and type(child_id) is int
                and child_id > 0
                and record.get("url")
                == (f"https://github.com/OWNER/REPO/pull/1#discussion_r{child_id}")
                and exact_provider(record)
                and type(record.get("pull_request_review_id")) is int
                and record.get("pull_request_review_id") == parent_id
                and record.get("commit_id") == commit_id
                and record.get("original_commit_id") == commit_id
                and bool(body)
                and record.get("normalized_body") == body
            )

        def classify(record: dict[str, object]) -> str:
            if not exact_provider(record):
                return "malformed"
            channel = record.get("channel")
            state = record.get("state")
            if channel == "review" and state == "PENDING":
                return "nonterminal"
            body = normalize_body(record.get("body"))
            if body is None:
                return "malformed"
            if channel == "issue-comment":
                if record.get("app_slug") != "chatgpt-codex-connector":
                    return "malformed"
                clean_marker = _github_codex_clean_issue_marker(body)
                resolved_clean_commit = (
                    current_sha
                    if clean_marker is not None and clean_marker[1] == current_sha[:10]
                    else None
                )
                semantic, _ = _github_codex_issue_body_semantic(
                    body,
                    repository="OWNER/REPO",
                    head=current_sha,
                    resolved_clean_commit=resolved_clean_commit,
                )
                return semantic
            if channel != "review":
                return "malformed"
            children = record.get("children")
            if _github_codex_invalid_review_state_terminal_signal(
                body,
                state=state,
                has_associated_children=(isinstance(children, list) and bool(children)),
            ):
                return "malformed"
            if state not in ("APPROVED", "COMMENTED", "CHANGES_REQUESTED"):
                return "nonterminal"
            commit_id = record.get("commit_id")
            parent_id = record.get("id")
            children = record.get("children")
            if (
                type(parent_id) is not int
                or parent_id <= 0
                or not isinstance(children, list)
            ):
                return "malformed"
            target_children = _selected_review_target_children(
                children,
                repository="OWNER/REPO",
                pull_request=1,
                parent_review_id=parent_id,
            )
            if target_children is None:
                return "malformed"
            thread_findings = _review_thread_findings_from_raw(
                children,
                record.get("review_thread_pages"),
                repository="OWNER/REPO",
                pull_request=1,
                parent_review_id=parent_id,
            )
            if thread_findings is None:
                return "malformed"
            if state == "APPROVED":
                if body != "No findings." or (
                    not target_children and commit_id != current_sha
                ):
                    return "malformed"
                child_ids: set[int] = set()
                for child_record in target_children:
                    if (
                        not exact_inline_child(
                            child_record,
                            parent_id=parent_id,
                            commit_id=commit_id,
                        )
                        or child_record["id"] in child_ids
                    ):
                        return "malformed"
                    child_ids.add(child_record["id"])
                return "findings" if target_children else "clean"
            found_sha = finding_sha(body)
            if found_sha is not None:
                return (
                    "findings"
                    if state in ("COMMENTED", "CHANGES_REQUESTED")
                    and commit_id == found_sha
                    else "malformed"
                )
            if (
                state != "COMMENTED"
                or commit_id not in eligible_finding_commits
                or body not in ("", inline_container(str(commit_id)))
                or not target_children
            ):
                return "malformed"
            child_ids = set()
            for child in target_children:
                if (
                    not exact_inline_child(
                        child,
                        parent_id=parent_id,
                        commit_id=commit_id,
                    )
                    or child["id"] in child_ids
                ):
                    return "malformed"
                child_ids.add(child["id"])
            return "findings"

