        class RaisingWrapperList(list[object]):
            def __init__(
                self,
                values: list[object],
                *,
                reported_length: int,
                probe: str,
            ) -> None:
                super().__init__(values)
                self.reported_length = reported_length
                self.probe = probe

            def __len__(self) -> int:
                return self.reported_length

